begin;
select no_plan();
create function pg_temp.expect_error(command text,expected text) returns text language plpgsql as $$ declare caught text; begin
 begin execute command; exception when others then caught:=sqlerrm; end;
 if caught is null or position(expected in caught)=0 then raise exception 'Expected %, got % for %',expected,coalesce(caught,'SUCCESS'),command; end if;
 return ok(true,'Rejected with '||expected); end $$;
select ok(not has_function_privilege('service_role','public.request_appointment_change(uuid,uuid,text,text,text,text)','execute'),'legacy appointment change execute denied');
select ok(not has_function_privilege('service_role','public.create_customer_concierge_request(uuid,jsonb)','execute'),'legacy concierge create execute denied');
select ok(not has_function_privilege('service_role','public.add_customer_concierge_message(uuid,uuid,text)','execute'),'legacy concierge reply execute denied');
select pg_temp.expect_error($q$select public.request_appointment_change(null,null,null,null,null,null)$q$,'retired_rpc_use_authenticated_signature');
select pg_temp.expect_error($q$select public.create_customer_concierge_request(null,null)$q$,'retired_rpc_use_authenticated_signature');
select pg_temp.expect_error($q$select public.add_customer_concierge_message(null,null,null)$q$,'retired_rpc_use_authenticated_signature');
set local role service_role;
select set_config('app.phase6.trusted','true',true);
select set_config('tcc.atelier_rpc','true',true);
select set_config('request.jwt.claim.role','postgres',true);
select pg_temp.expect_error($q$select public.request_appointment_change('f3000000-0000-0000-0000-000000000001','f6900000-0000-0000-0000-000000000001','cancellation',null,null,null)$q$,'permission denied');
select pg_temp.expect_error($q$update public.appointments set status='confirmed' where id='f6900000-0000-0000-0000-000000000001'$q$,'permission denied');
select pg_temp.expect_error($q$delete from public.appointments where id='f6900000-0000-0000-0000-000000000001'$q$,'permission denied');
select pg_temp.expect_error($q$insert into public.appointments(customer_id,type,preferred_date,preferred_time,status) values('f3000000-0000-0000-0000-000000000001','measurement','2099-01-01','morning','confirmed')$q$,'appointment_requires_request');
select pg_temp.expect_error($q$insert into public.concierge_messages(request_id,sender_type,sender_id,sender_name,message) values('f6910000-0000-0000-0000-000000000001','concierge',null,'TCC Concierge','fake staff')$q$,'permission denied');
select pg_temp.expect_error($q$update public.concierge_messages set message='altered'$q$,'permission denied');
select pg_temp.expect_error($q$delete from public.concierge_messages$q$,'permission denied');
select pg_temp.expect_error($q$update public.concierge_requests set staff_read_seq=last_message_seq$q$,'permission denied');
select pg_temp.expect_error($q$insert into public.appointment_change_requests(appointment_id,customer_id,change_type) values('f6900000-0000-0000-0000-000000000001','f3000000-0000-0000-0000-000000000001','cancellation')$q$,'permission denied');
select pg_temp.expect_error($q$select * from private.atelier_operation_results$q$,'permission denied');
select public.submit_public_fitting_request('f3000000-0000-0000-0000-000000000001','{"customer_name":"Synthetic account","email":"phase6@example.invalid","phone":"00000","appointment_type":"first-fitting","preferred_date":"2099-01-01","preferred_time":"morning"}');
select public.submit_public_fitting_request(null,'{"customer_name":"Synthetic public","email":"phase6@example.invalid","phone":"00000","appointment_type":"first-fitting","preferred_date":"2099-01-01","preferred_time":"afternoon"}');
select ok((select count(*)=1 from public.appointments where preferred_date='2099-01-01' and customer_id='f3000000-0000-0000-0000-000000000001'),'minimum public fitting permissions preserve one authenticated request, no anonymous appointment');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','f3000000-0000-0000-0000-000000000001',true);
select pg_temp.expect_error($q$select * from public.concierge_messages$q$,'permission denied');
select pg_temp.expect_error($q$select sender_name from public.concierge_messages$q$,'permission denied');
select pg_temp.expect_error($q$select sender_id from public.concierge_messages$q$,'permission denied');
select ok((select count(*)=3 from public.concierge_messages where request_id='f6910000-0000-0000-0000-000000000001'),'safe raw columns still have ownership RLS');
select ok(public.get_atelier_concierge_thread('f6910000-0000-0000-0000-000000000001',0,100)->'messages'->1->>'sender_name'='TCC Concierge','legacy internal sender name safely projected');
select pg_temp.expect_error($q$insert into public.concierge_messages(request_id,sender_type,sender_id,sender_name,message) values('f6910000-0000-0000-0000-000000000001','customer','f3000000-0000-0000-0000-000000000001','Client','bypass')$q$,'permission denied');
select pg_temp.expect_error($q$update public.concierge_requests set client_read_seq=3$q$,'permission denied');
select pg_temp.expect_error($q$select public.get_atelier_concierge_thread('f6910000-0000-0000-0000-000000000001',null,10)$q$,'invalid_pagination');
reset role;
select * from finish();
rollback;
